	int signalNormal[187] = {0};
	int signalAbnorm[187] = {0};

	int inferenceResultNormal;
	int inferenceResultAbnorm;

	int inferenceClass1 = 0;
	int inferenceClass2 = 0;

	int inferenceClass1_2 = 0;
	int inferenceClass2_1 = 0;

	// Load stream

	int nTraces = 100;
	int nSamples = 187;

	for (int k = 0; k < nSamples * nTraces; k = k + nSamples)
	{

		int i = 0;

		for (int t = 0; t < nSamples; t++)
		{

			signalNormal[t] = tracesNormal[t + k];
			signalAbnorm[t] = tracesAbnorm[t + k];

			i++;
		}
		std::cout << std::endl;

		for (int g = 0; g < nSamples; g++)
		{

			AXI_VALUE_IN valG;

			valG.data = signalNormal[g];
			valG.keep = 1;
			valG.strb = 1;
			valG.user = 1;
			valG.id = 0;
			valG.dest = 0;
			inputsignalNormal << valG;
			// std::cout << " " << signalNormal[g];
		}
		// std::cout << std::endl;

		GN_inference(inputsignalNormal, &inferenceResultNormal);

		std::cout << "Output inference Normal: " << inferenceResultNormal << std::endl;

		if (inferenceResultNormal == 5)
		{
			inferenceClass1++;
		}
		else
		{
			inferenceClass1_2++;
		}

		for (int gg = 0; gg < nSamples; gg++)
		{

			AXI_VALUE_IN valN;

			valN.data = signalAbnorm[gg];
			valN.keep = 1;
			valN.strb = 1;
			valN.user = 1;
			valN.id = 0;
			valN.dest = 0;
			inputsignalAbnorm << valN;
			// std::cout << " " << signalAbnorm[gg];
		}
		// std::cout << std::endl;

		GN_inference(inputsignalAbnorm, &inferenceResultAbnorm);

		std::cout << "Output inference Abnorm: " << inferenceResultAbnorm << std::endl;

		if (inferenceResultAbnorm == 3)
		{
			inferenceClass2++;
		}
		else
		{
			inferenceClass2_1++;
		}
	}

	std::cout << "--------------- Total counting" << std::endl;

	std::cout << "Normal: " << inferenceClass1 << std::endl;
	std::cout << "Abnorm: " << inferenceClass2 << std::endl;
	std::cout << "Normal as Abnorm: " << inferenceClass1_2 << std::endl;
	std::cout << "Abnorm as Normal: " << inferenceClass2_1 << std::endl;

	return 0;
